<script>
import axios from 'axios';

export default {
    name: 'BogotaMapa',
    data() {
        return {
            votantesPorLocalidad: [],
            tooltip: {
                visible: false,
                x: 0,
                y: 0,
                titulo: '',
                votantes: 0
            }
        }
    },
    mounted() {
        this.$nextTick(() => {
            this.obtenerVotantesPorLocalidad();
        });
    },
    methods: {
        obtenerVotantesPorLocalidad() {
            // Llamada al API para obtener votantes por localidad de Bogotá
            axios.get('/api/votantesxlocalidad', {
                headers: {
                    "Authorization": `Bearer ${this.$store.state.user.token}`
                }
            })
            .then(response => {
                // Verificar la estructura de los datos recibidos
                console.log('Datos completos recibidos:', response.data);
                
                // Manejar diferentes estructuras de respuesta del API
                let datosVotantes = [];
                if (response.data.votantes_por_localidad) {
                    datosVotantes = response.data.votantes_por_localidad;
                } else if (Array.isArray(response.data)) {
                    datosVotantes = response.data;
                } else if (response.data.data && Array.isArray(response.data.data)) {
                    datosVotantes = response.data.data;
                }
                
                this.votantesPorLocalidad = datosVotantes;
                console.log('Array de votantes procesado:', this.votantesPorLocalidad);
                
                // Mostrar estructura del primer elemento para debug
                if (datosVotantes.length > 0) {
                    console.log('Estructura del primer elemento:', datosVotantes[0]);
                    console.log('Claves disponibles:', Object.keys(datosVotantes[0]));
                }
                
                // Configurar tooltips después de recibir los datos
                if (Array.isArray(this.votantesPorLocalidad) && this.votantesPorLocalidad.length > 0) {
                    this.$nextTick(() => {
                        this.configurarTooltips();
                    });
                } else {
                    console.warn('No se recibieron datos válidos para configurar tooltips');
                }
            })
            .catch(error => {
                // Manejar errores
                console.error('Error al obtener votantes por localidad:', error);
            });
        },
        
        configurarTooltips() {
            // Verificar que tenemos datos válidos
            if (!Array.isArray(this.votantesPorLocalidad)) {
                console.error('votantesPorLocalidad no es un array:', this.votantesPorLocalidad);
                return;
            }
            
            // Obtener todos los paths del SVG
            const paths = document.querySelectorAll('svg path[id]');
            console.log(`Encontrados ${paths.length} paths en el SVG`);
            
            paths.forEach(path => {
                const localidadId = parseInt(path.id);
                
                // Buscar los datos correspondientes en el array
                const datosVotantes = this.votantesPorLocalidad.find(
                    item => item.localidad_id === localidadId
                );
                
                if (datosVotantes) {
                    // Aplicar colores basados en el número de votantes
                    this.aplicarColorLocalidad(path, datosVotantes.votantes_confirmados);
                    
                    // Configurar eventos de mouse para el tooltip
                    path.addEventListener('mouseover', (event) => {
                        this.mostrarTooltip(event, datosVotantes.votantes_confirmados, datosVotantes.localidad);
                    });
                    
                    path.addEventListener('mousemove', (event) => {
                        this.actualizarPosicionTooltip(event);
                    });
                    
                    path.addEventListener('mouseout', () => {
                        this.ocultarTooltip();
                    });
                    
                    console.log(`✓ Tooltip y color configurado para localidad ${localidadId}: ${datosVotantes.votantes_confirmados} votantes`);
                } else {
                    console.log(`✗ No se encontraron datos para localidad ${localidadId}`);
                }
            });
        },
        
        mostrarTooltip(event, votantesConfirmados, localidad) {
            this.tooltip.visible = true;
            this.tooltip.titulo = localidad;
            this.tooltip.votantes = votantesConfirmados || 0;
            this.actualizarPosicionTooltip(event);
        },
        
        actualizarPosicionTooltip(event) {
            this.tooltip.x = event.clientX + 10;
            this.tooltip.y = event.clientY - 10;
        },
        
        ocultarTooltip() {
            this.tooltip.visible = false;
        },
        
        aplicarColorLocalidad(path, votantesConfirmados) {
            // Solo aplicar color verde suave si tiene más de 0 votantes
            if (votantesConfirmados > 0) {
                // Verde suave para localidades con votantes
                path.style.fill = '#a8e6a3'; // Verde suave
                path.style.stroke = '#ffffff';
                path.style.strokeWidth = '1';
                
                // Agregar clase para hover mejorado
                path.classList.add('localidad-con-votantes');
            } else {
                // Mantener color gris por defecto para localidades sin votantes
                path.style.fill = '#808080';
                path.style.stroke = '#ffffff';
                path.style.strokeWidth = '0.5';
            }
        }
    }
};
</script>

<style type="text/css">
/* Contenedor del SVG - altura fija calculada del viewport sin desbordamiento */
.contenedor-mapa {
    width: 100%;
    height: calc(100vh - 120px); /* Altura del viewport menos espacio para header/navbar */
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

/* SVG que se ajusta al contenedor manteniendo proporciones sin generar scroll */
.contenedor-mapa svg {
    max-width: 100%;
    max-height: 100%;
    width: auto;
    height: auto;
    display: block;
    margin: 0;
    padding: 0;
}

/* Estilos de las localidades del mapa */
.contenedor-mapa .st0 {
    fill: #808080;
    stroke: #FFFFFF;
    stroke-width: 0.5;
    stroke-linecap: round;
    stroke-linejoin: round;
    transition: fill 0.3s ease, stroke-width 0.3s ease;
}

.contenedor-mapa .st0:hover {
    fill: #007bff;
    stroke-width: 1;
    cursor: pointer;
}

/* Texto del mapa */
.contenedor-mapa .st1 {
    font-family: 'Roboto-Regular', Arial, sans-serif;
}

.contenedor-mapa .st2 {
    font-size: 14px;
}

/* Media queries para diferentes tamaños de pantalla */
@media (max-width: 768px) {
    .contenedor-mapa .st2 {
        font-size: 12px;
    }
}

@media (max-width: 480px) {
    .contenedor-mapa .st2 {
        font-size: 10px;
    }
}

/* Estilos para el tooltip del mapa */
.mapa-tooltip {
    position: fixed;
    background: linear-gradient(135deg, rgba(40, 167, 69, 0.95), rgba(25, 135, 84, 0.95));
    color: white;
    padding: 12px 16px;
    border-radius: 8px;
    min-width: 180px;
    z-index: 9999;
    pointer-events: none;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.4);
    border: 1px solid rgba(255, 255, 255, 0.3);
    transition: all 0.2s ease;
    backdrop-filter: blur(5px);
}

/* Título de la localidad - centrado */
.tooltip-titulo {
    font-size: 16px;
    font-weight: 700;
    text-align: center;
    margin-bottom: 6px;
    color: #ffffff;
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.5);
    border-bottom: 1px solid rgba(255, 255, 255, 0.3);
    padding-bottom: 6px;
}

/* Información de votantes */
.tooltip-votantes {
    font-size: 14px;
    font-weight: 500;
    text-align: center;
    color: #f8f9fa;
    margin-top: 6px;
}

/* Hacer los paths del mapa interactivos */
.contenedor-mapa svg path[id] {
    cursor: pointer;
    transition: fill 0.3s ease, stroke-width 0.2s ease, filter 0.2s ease;
}

.contenedor-mapa svg path[id]:hover {
    stroke-width: 1.5;
    filter: brightness(1.1);
}

/* Estilos específicos para localidades con votantes */
.contenedor-mapa svg path.localidad-con-votantes {
    fill: #a8e6a3 !important; /* Verde suave */
    stroke: #ffffff !important;
    stroke-width: 1 !important;
}

.contenedor-mapa svg path.localidad-con-votantes:hover {
    fill: #85d47f !important; /* Verde más intenso en hover */
    stroke-width: 2 !important;
    filter: brightness(1.1) drop-shadow(0 0 3px rgba(168, 230, 163, 0.6));
}
</style>